const state={tenantId:localStorage.getItem('tenantId')||'sentire-customs-broker',data:null,page:'dashboard',draft:{},calc:null};
const $=s=>document.querySelector(s);
const money=n=>`USD ${Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const pct=n=>`${Number(n||0)}%`;
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'x-tenant-id':state.tenantId};if(opt.body&&!(opt.body instanceof FormData)){opt.headers['content-type']='application/json';opt.body=JSON.stringify(opt.body)}const r=await fetch(url,opt);if(!r.ok){let e;try{e=await r.json()}catch{e={error:await r.text()}}throw new Error(e.error||'Error');}return r.headers.get('content-type')?.includes('application/json')?r.json():r;}
async function boot(){try{state.data=await api('/api/bootstrap');$('#tenantSelect').value=state.tenantId;applyTenant();renderNav();route('dashboard');}catch(e){$('#content').innerHTML=`<div class="content"><div class="notice">Error iniciando: ${esc(e.message)}</div></div>`}}
function applyTenant(){const t=state.data.tenant;$('#tenantLogo').src=t.logo;$('#tenantNameSide').textContent=t.name;$('#tenantCardName').textContent=t.name;}
function renderNav(){const isLog=state.data.tenant.module==='logistics';const nav=[['dashboard','▦ Dashboard'],['products',isLog?'◫ Ítems de mercadería':'◫ Productos'],['quotes','▤ Cotizaciones'],...(isLog?[['logistics','⚓ Cotizaciones logísticas'],['profiles','⚙ Perfiles y permisos']]:[['catalog','▥ Catálogos'],['profiles','⚙ Perfiles y permisos']]),['clients','♙ Clientes']];$('#nav').innerHTML=nav.map(([id,label])=>`<button class="nav-item ${state.page===id?'active':''}" onclick="route('${id}')"><span>${label}</span></button>`).join('')}
function route(page){state.page=page;renderNav();const fn={dashboard,products,quotes,logistics,profiles,catalog,clients}[page]||dashboard;fn();}
function shell(title,sub,actions=''){$('#pageTitle').textContent=title;$('#content').innerHTML=`<div class="content"><div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div><div>${actions}</div></div><div id="pageBody"></div></div>`}
function dashboard(){shell(state.data.tenant.module==='logistics'?'Dashboard Logística':'Dashboard','Resumen operativo de MRAPI Quotes.');const d=state.data;const quotes=d.quotes||[];$('#pageBody').innerHTML=`<div class="grid kpis"><div class="kpi"><small>Productos cargados</small><strong>${d.products.length}</strong></div><div class="kpi"><small>Cotizaciones</small><strong>${quotes.length}</strong></div><div class="kpi"><small>Perfiles logísticos</small><strong>${d.logisticsProfiles.length}</strong></div><div class="kpi"><small>Perfiles impositivos</small><strong>${d.taxProfiles.length}</strong></div></div><br><div class="grid split"><div class="card"><h3>Cotizaciones recientes</h3>${quotesTable(quotes.slice(0,10))}</div><div class="card"><h3>Acciones rápidas</h3><div class="actions"><button class="btn primary" onclick="newQuote('${state.data.tenant.module==='logistics'?'logistics':'product'}')">+ Nueva cotización</button><button class="btn" onclick="route('products')">Productos</button><button class="btn" onclick="route('profiles')">Perfiles</button></div><div class="notice">Los cambios de perfiles se aplican a nuevas cotizaciones. Las emitidas conservan snapshot.</div></div></div>`}
function quotesTable(qs){return `<div class="table-wrap"><table><thead><tr><th>Proforma</th><th>Cliente</th><th>Tipo</th><th>FOB</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody>${qs.length?qs.map(q=>`<tr><td>${esc(q.quoteNo||q.id)}</td><td>${esc(q.clientName||'-')}</td><td>${esc(q.mode||q.logisticsProfileSnapshot?.name||'-')}</td><td>${money(q.calculation?.fob)}</td><td>${money(q.calculation?.totalToPay)}</td><td><span class="status">${esc(q.status||'draft')}</span></td><td>${q.id?`<button class="ghost" onclick="window.open('/api/quotes/${q.id}/pdf?tenantId=${state.tenantId}')">PDF</button>`:''}</td></tr>`).join(''):`<tr><td colspan="7">Todavía no hay cotizaciones.</td></tr>`}</tbody></table></div>`}
function productsTradingV29(){shell('Base de productos','Productos, categorías y proveedores de Shenzhen Trading.',`<button class="btn primary" onclick="productModal()">+ Nuevo producto</button> <button class="btn" onclick="importModal()">Carga masiva</button>`);const ps=state.data.products||[];$('#pageBody').innerHTML=`<div class="card"><div class="toolbar"><input id="psearch" placeholder="Buscar SKU, producto o categoría..." oninput="filterProducts()"><span>${ps.length} productos</span></div><div id="ptable">${productTable(ps)}</div></div><br><div class="grid product-admin-grid"><div class="card"><div class="section-head"><div><h3>Categorías</h3><small>${(state.data.categories||[]).length} guardadas</small></div><button class="ghost" onclick="categoryModal()">+ Nueva</button></div>${categoriesTable()}</div><div class="card"><div class="section-head"><div><h3>Proveedores</h3><small>Nombre real privado · alias externo</small></div><button class="ghost" onclick="supplierModal()">+ Nuevo</button></div>${suppliersTable()}</div></div>`}

function products(){if(state.data.tenant.module!=='logistics')return productsTradingV29();const recent=[];(state.data.quotes||[]).forEach(q=>(q.items||[]).forEach(i=>recent.push({quoteNo:q.quoteNo||q.id,name:i.name||'-',fob:(+i.unitFob||0)*(+i.qty||1),cbm:(+i.unitCbm||0)*(+i.qty||1),use:i.productUse||'commercial',tax:i.taxProfileId||'-'})));shell('Ítems de mercadería','En Logística los ítems pertenecen a cada cotización. SCB vende logística y aduana, no la mercadería.',`<button class="btn primary" onclick="newQuote('logistics')">+ Nueva cotización logística</button>`);$('#pageBody').innerHTML=`<div class="notice"><b>Cómo funciona:</b> agregá uno o varios ítems dentro de la cotización. Cada ítem puede tener FOB, CBM, KG, uso y perfil impositivo diferente.</div><br><div class="card"><h3>Ítems recientes</h3><div class="table-wrap"><table><thead><tr><th>Cotización</th><th>Ítem</th><th>FOB</th><th>CBM</th><th>Uso</th><th>Perfil</th></tr></thead><tbody>${recent.slice(0,60).map(i=>`<tr><td>${esc(i.quoteNo)}</td><td><b>${esc(i.name)}</b></td><td>${money(i.fob)}</td><td>${Number(i.cbm).toFixed(3)}</td><td>${useLabel(i.use)}</td><td>${esc(i.tax)}</td></tr>`).join('')||'<tr><td colspan="6">Todavía no hay ítems guardados en cotizaciones.</td></tr>'}</tbody></table></div></div>`}
function productTable(ps){return `<div class="table-wrap"><table><thead><tr><th>Foto</th><th>SKU</th><th>Producto</th><th>Categoría</th><th>Proveedor/es</th><th>FOB</th><th>CBM</th><th>Comisión</th><th></th></tr></thead><tbody>${ps.map(p=>{const supp=(p.supplierIds||[]).map(id=>(state.data.suppliers||[]).find(s=>s.id===id)?.publicAlias||'Proveedor').join(', ')||'-';return `<tr><td><img class="thumb" src="${esc(p.imageUrl||'/assets/shenzhen-logo.png')}"></td><td>${esc(p.sku||p.id)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.category||'-')}</td><td>${esc(supp)}</td><td><b>${money(p.fob)}</b><br><small>${(p.prices||[]).length?`${(p.prices||[]).length} precio(s)`:'Precio base'}</small></td><td>${Number(p.cbm||0).toFixed(3)}</td><td>${pct(p.agentCommissionPct||0)}</td><td><div class="row-actions"><button class="ghost" onclick="productModal('${p.id}')">Editar</button><button class="ghost danger" onclick="deleteProduct('${p.id}')">Borrar</button></div></td></tr>`}).join('')||`<tr><td colspan="9">Sin productos todavía.</td></tr>`}</tbody></table></div>`}
function filterProducts(){const q=$('#psearch').value.toLowerCase();$('#ptable').innerHTML=productTable(state.data.products.filter(p=>`${p.sku} ${p.name} ${p.category}`.toLowerCase().includes(q)))}
function productPriceRow(pr={},idx=Date.now()){const suppliers=state.data.suppliers||[];return `<div class="formula-line product-price-row" data-price-row data-price-id="${esc(pr.id||`pr_${idx}`)}"><div class="line-row price-line"><input class="price-list" placeholder="Lista / condición" value="${esc(pr.listName||'Standard')}"><select class="price-supplier"><option value="">Sin proveedor</option>${suppliers.map(s=>`<option value="${s.id}" ${pr.supplierId===s.id?'selected':''}>${esc(s.publicAlias||s.name||'Proveedor')}</option>`).join('')}</select><input class="price-currency" value="${esc(pr.currency||'USD')}" placeholder="Moneda"><input class="price-value" type="number" step=".0001" min="0" value="${Number(pr.price||0)}" placeholder="Precio"><input class="price-moq" type="number" step="1" min="0" value="${Number(pr.moq||0)}" placeholder="MOQ"><label style="display:flex;align-items:center;gap:6px;white-space:nowrap"><input type="radio" name="pPriceDefault" class="price-default" ${pr.isDefault?'checked':''}> Default</label><button class="ghost danger" type="button" onclick="this.closest('[data-price-row]').remove()">✕</button></div><div class="line-row"><label>Desde <input class="price-from" type="date" value="${esc(pr.validFrom||'')}"></label><label>Hasta <input class="price-to" type="date" value="${esc(pr.validTo||'')}"></label><input class="price-notes" placeholder="Notas / condición comercial" value="${esc(pr.notes||'')}"></div></div>`}
function addProductPriceRow(){const box=$('#productPrices');if(box)box.insertAdjacentHTML('beforeend',productPriceRow({},Date.now()))}
function readProductPrices(){const rows=[...document.querySelectorAll('[data-price-row]')];let prices=rows.map((r,i)=>({id:r.dataset.priceId||`pr_${Date.now()}_${i}`,listName:r.querySelector('.price-list')?.value.trim()||'Standard',supplierId:r.querySelector('.price-supplier')?.value||'',currency:r.querySelector('.price-currency')?.value.trim()||'USD',price:+(r.querySelector('.price-value')?.value||0),moq:+(r.querySelector('.price-moq')?.value||0),validFrom:r.querySelector('.price-from')?.value||'',validTo:r.querySelector('.price-to')?.value||'',notes:r.querySelector('.price-notes')?.value||'',isDefault:!!r.querySelector('.price-default')?.checked}));if(prices.length&&!prices.some(x=>x.isDefault))prices[0].isDefault=true;return prices}
function productModal(pid){
  const p=state.data.products.find(x=>x.id===pid)||{};
  const categories=[...new Set([...(state.data.categories||[]).map(c=>c.name),...(state.data.products||[]).map(x=>x.category)].filter(Boolean))].sort();
  const selectedSuppliers=new Set(p.supplierIds||[]);
  openModal(pid?'Editar producto':'Nuevo producto',`<div class="product-edit-grid"><div><div class="image-upload-card"><img id="pImagePreview" src="${esc(p.imageUrl||'/assets/shenzhen-logo.png')}" class="product-image-preview"><div><b>Foto del producto</b><p>JPG, PNG o WEBP</p><input type="file" id="pImageFile" accept="image/jpeg,image/png,image/webp" onchange="previewProductImage(this)"></div></div><br><div class="form-grid"><div class="field"><label>SKU</label><input id="pSku" value="${esc(p.sku||'')}"></div><div class="field span2"><label>Producto</label><input id="pName" value="${esc(p.name||'')}"></div><div class="field"><label>Categoría</label><input id="pCat" list="categoryList" value="${esc(p.category||'')}" placeholder="Buscar o crear categoría"><datalist id="categoryList">${categories.map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist><small>Escribí para buscar. Si no existe, se crea al guardar.</small></div><div class="field"><label>FOB USD</label><input type="number" step=".01" id="pFob" value="${p.fob||0}"></div><div class="field"><label>CBM</label><input type="number" step=".001" id="pCbm" value="${p.cbm||0}"></div><div class="field"><label>KG</label><input type="number" step=".01" id="pKg" value="${p.kg||0}"></div><div class="field"><label>MOQ</label><input type="number" id="pMoq" value="${p.moq||0}"></div><div class="field"><label>Comisión agente compra %</label><input type="number" step=".01" id="pCom" value="${p.agentCommissionPct||0}" placeholder="3, 4 o 6"></div><div class="field span2"><label>Uso impositivo</label><select id="pUse"><option value="commercial" ${(!p.productUse||p.productUse==='commercial')?'selected':''}>COMERCIAL</option><option value="capital_good" ${(p.productUse==='capital_good'||p.productUse==='bien_de_uso')?'selected':''}>BIEN DE USO</option><option value="particular" ${p.productUse==='particular'?'selected':''}>PARTICULAR</option></select></div><div class="field span2"><label>Perfil impositivo</label><select id="pTax">${state.data.taxProfiles.map(x=>`<option value="${x.id}" ${p.taxProfileId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div></div><div><div class="relation-card"><div class="section-head"><div><h4>Proveedores del producto</h4><small>Los nombres reales son internos. Administralos desde la pantalla Productos.</small></div></div><div class="supplier-checks">${(state.data.suppliers||[]).length?(state.data.suppliers||[]).map(s=>`<label class="supplier-check"><input type="checkbox" class="pSupplier" value="${s.id}" ${selectedSuppliers.has(s.id)?'checked':''}><span><b>${esc(s.publicAlias||'Proveedor')}</b><small>${esc(s.name||'')}</small></span></label>`).join(''):'<div class="notice">Todavía no cargaste proveedores.</div>'}</div></div><br><div class="notice"><b>Privacidad:</b> en documentos para clientes se usa el alias externo (Proveedor 1, Proveedor 2, etc.). El nombre real queda interno.</div></div></div><br><div class="relation-card"><div class="section-head"><div><h4>Listas / precios del producto</h4><small>El mismo producto puede tener varios precios por proveedor, lista, MOQ o vigencia.</small></div><button class="ghost" type="button" onclick="addProductPriceRow()">+ Agregar precio</button></div><div id="productPrices">${((p.prices||[]).length?p.prices:[{id:'base',listName:'Standard',supplierId:(p.supplierIds||[])[0]||'',currency:'USD',price:p.fob||0,moq:p.moq||0,isDefault:true}]).map((pr,i)=>productPriceRow(pr,i)).join('')}</div></div><br><div class="modal-actions"><button class="btn primary" onclick="saveProduct('${pid||''}')">Guardar producto</button>${pid?`<button class="btn danger" onclick="deleteProduct('${pid}')">Borrar producto</button>`:''}</div>`)
}
function previewProductImage(input){const f=input.files?.[0];if(!f)return;const url=URL.createObjectURL(f);const img=$('#pImagePreview');if(img)img.src=url}
async function saveProduct(pid){
  const category=$('#pCat').value.trim();
  const prices=readProductPrices();const defaultPrice=prices.find(x=>x.isDefault)||prices[0];const body={sku:$('#pSku').value.trim(),name:$('#pName').value.trim(),category,fob:defaultPrice?+defaultPrice.price:+$('#pFob').value,cbm:+$('#pCbm').value,kg:+$('#pKg').value,moq:defaultPrice?.moq||+$('#pMoq').value,agentCommissionPct:+($('#pCom')?.value||0),taxProfileId:$('#pTax').value,productUse:$('#pUse').value,supplierIds:[...document.querySelectorAll('.pSupplier:checked')].map(x=>x.value),prices,active:true};
  if(!body.name)return alert('Producto es obligatorio');
  if(category && !(state.data.categories||[]).some(c=>String(c.name).toLowerCase()===category.toLowerCase())) await api('/api/categories',{method:'POST',body:{name:category,active:true}});
  const r=await api(pid?`/api/products/${pid}`:'/api/products',{method:pid?'PUT':'POST',body});
  const productId=pid||r.id;
  const image=$('#pImageFile')?.files?.[0];
  if(image){const fd=new FormData();fd.append('image',image);await api(`/api/products/${encodeURIComponent(productId)}/image`,{method:'POST',body:fd});}
  closeModal();await refresh();route('products')
}
async function deleteProduct(pid){if(!confirm('¿Borrar este producto? Esta acción no elimina las cotizaciones históricas.'))return;await api(`/api/products/${pid}`,{method:'DELETE'});closeModal();await refresh();route('products')}
function categoriesTable(){const rows=[...(state.data.categories||[])].sort((a,b)=>String(a.name).localeCompare(String(b.name)));return `<div class="mini-search"><input id="catSearch" placeholder="Buscar categoría..." oninput="filterCategoryAdmin()"></div><div id="categoryAdminTable"><div class="admin-list">${rows.map(c=>`<div><span>${esc(c.name)}</span><div><button class="ghost" onclick="categoryModal('${c.id}')">Editar</button><button class="ghost danger" onclick="deleteAdminItem('categories','${c.id}')">×</button></div></div>`).join('')||'<small>Sin categorías.</small>'}</div></div>`}
function filterCategoryAdmin(){const q=$('#catSearch')?.value.toLowerCase()||'';const rows=(state.data.categories||[]).filter(c=>String(c.name).toLowerCase().includes(q));$('#categoryAdminTable').innerHTML=`<div class="admin-list">${rows.map(c=>`<div><span>${esc(c.name)}</span><div><button class="ghost" onclick="categoryModal('${c.id}')">Editar</button><button class="ghost danger" onclick="deleteAdminItem('categories','${c.id}')">×</button></div></div>`).join('')||'<small>Sin resultados.</small>'}</div>`}
function categoryModal(id){const c=(state.data.categories||[]).find(x=>x.id===id)||{};openModal(id?'Editar categoría':'Nueva categoría',`<div class="form-grid"><div class="field span4"><label>Nombre</label><input id="catName" value="${esc(c.name||'')}"></div></div><br><button class="btn primary" onclick="saveCategory('${id||''}')">Guardar</button>`)}
async function saveCategory(id){const name=$('#catName').value.trim();if(!name)return alert('Nombre requerido');await api(id?`/api/categories/${id}`:'/api/categories',{method:id?'PUT':'POST',body:{name,active:true}});closeModal();await refresh();route('products')}
function suppliersTable(){const rows=state.data.suppliers||[];return `<div class="mini-search"><input id="supplierSearch" placeholder="Buscar alias, nombre interno, contacto, ciudad o moneda..." oninput="filterSupplierAdmin()"></div><div id="supplierAdminTable"><div class="admin-list">${rows.map(s=>`<div><span><b>${esc(s.publicAlias||'Proveedor')}</b><small>${esc(s.name||'')} · ${esc(s.contact||'-')} · ${esc(s.city||'-')} · ${esc(s.currency||'USD')}</small></span><div><button class="ghost" onclick="supplierModal('${s.id}')">Editar</button><button class="ghost danger" onclick="deleteAdminItem('suppliers','${s.id}')">×</button></div></div>`).join('')||'<small>Sin proveedores.</small>'}</div></div>`}
function filterSupplierAdmin(){const q=$('#supplierSearch')?.value.toLowerCase()||'';const rows=(state.data.suppliers||[]).filter(s=>`${s.publicAlias||''} ${s.name||''} ${s.contact||''} ${s.city||''} ${s.currency||''}`.toLowerCase().includes(q));$('#supplierAdminTable').innerHTML=`<div class="admin-list">${rows.map(s=>`<div><span><b>${esc(s.publicAlias||'Proveedor')}</b><small>${esc(s.name||'')} · ${esc(s.contact||'-')} · ${esc(s.city||'-')} · ${esc(s.currency||'USD')}</small></span><div><button class="ghost" onclick="supplierModal('${s.id}')">Editar</button><button class="ghost danger" onclick="deleteAdminItem('suppliers','${s.id}')">×</button></div></div>`).join('')||'<small>Sin resultados.</small>'}</div>`}
function supplierModal(id){const s=(state.data.suppliers||[]).find(x=>x.id===id)||{};const suggested=s.publicAlias||`Proveedor ${(state.data.suppliers||[]).length+1}`;openModal(id?'Editar proveedor':'Nuevo proveedor',`<div class="form-grid"><div class="field span2"><label>Nombre real (privado)</label><input id="sName" value="${esc(s.name||'')}"></div><div class="field span2"><label>Alias externo</label><input id="sAlias" value="${esc(suggested)}"></div><div class="field"><label>Contacto</label><input id="sContact" value="${esc(s.contact||'')}"></div><div class="field"><label>Ciudad</label><input id="sCity" value="${esc(s.city||'')}"></div><div class="field"><label>Moneda</label><input id="sCurrency" value="${esc(s.currency||'USD')}"></div><div class="field"><label>Lead time (días)</label><input type="number" id="sLead" value="${s.leadTimeDays||0}"></div><div class="field span4"><label>Notas internas</label><textarea id="sNotes">${esc(s.notes||'')}</textarea></div></div><br><button class="btn primary" onclick="saveSupplier('${id||''}')">Guardar proveedor</button>`)}
async function saveSupplier(id){const body={name:$('#sName').value.trim(),publicAlias:$('#sAlias').value.trim(),contact:$('#sContact').value,city:$('#sCity').value,currency:$('#sCurrency').value||'USD',leadTimeDays:+($('#sLead').value||0),notes:$('#sNotes').value,active:true};if(!body.name)return alert('Nombre real requerido');await api(id?`/api/suppliers/${id}`:'/api/suppliers',{method:id?'PUT':'POST',body});closeModal();await refresh();route('products')}
async function deleteAdminItem(entity,id){if(!confirm('¿Eliminar este registro?'))return;await api(`/api/${entity}/${id}`,{method:'DELETE'});await refresh();route('products')}
function importModal(){openModal('Carga masiva de productos',`<div class="upload"><h3>Excel / CSV</h3><p>Columnas recomendadas: SKU, Producto, Categoria, FOB, CBM, KG, MOQ, ComisionAgenteCompra, PerfilImpositivo, Uso (commercial/capital_good/particular), Imagen</p><input type="file" id="importFile" accept=".xlsx,.xls,.csv"></div><br><button class="btn primary" onclick="doImport()">Validar y cargar</button><div id="importResult"></div>`)}
async function doImport(){const f=$('#importFile').files[0];if(!f)return alert('Elegí un archivo');const fd=new FormData();fd.append('file',f);fd.append('tenantId',state.tenantId);const r=await api('/api/products/import',{method:'POST',body:fd});$('#importResult').innerHTML=`<p><b>${r.imported}</b> importados de ${r.processed}. Errores: ${r.errors.length}</p>${r.errors.length?`<pre>${esc(JSON.stringify(r.errors.slice(0,20),null,2))}</pre>`:''}`;await refresh();}
function profiles(){shell('Perfiles y permisos','Lógica logística e impositiva separadas y editables.',`<button class="btn primary" onclick="taxModal()">+ Perfil impositivo</button> <button class="btn" onclick="logModal()">+ Perfil logístico</button>`);$('#pageBody').innerHTML=`<div class="grid split"><div><div class="card"><h3>Perfiles logísticos</h3>${logProfilesTable()}</div><br><div class="card"><h3>Perfiles impositivos</h3>${taxProfilesTable()}</div></div><div class="card"><h3>Acceso por usuario</h3><p style="color:var(--muted)">Los perfiles quedan separados por tenant. Próximo paso: permisos granulares por usuario/perfil.</p><div class="notice"><b>Versionado y snapshot</b><br>Una cotización guarda copia de los valores usados al momento de emitirla.</div></div></div>`}
function taxProfilesTable(){return `<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Derecho</th><th>IVA</th><th>IVA ADD</th><th>Ganancia</th><th>IIBB</th><th>Tasa</th><th></th></tr></thead><tbody>${state.data.taxProfiles.map(p=>`<tr><td>${esc(p.name)}</td><td>${pct(p.duty)}</td><td>${pct(p.vat)}</td><td>${pct(p.vatAdditional)}</td><td>${pct(p.earnings)}</td><td>${pct(p.iibb)}</td><td>${pct(p.statisticalFee)}</td><td><button class="ghost" onclick="taxModal('${p.id}')">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
function formulaLabel(l){const vat=l.vatTreatment==='plus_vat'?' + IVA 21%':l.vatTreatment==='included_vat'?' IVA incluido':'';if(l.basis!=='tiered_cbm')return (l.basis==='cbm'?`${money(l.amount)}/CBM`:l.basis==='kg'?`${money(l.amount)}/KG`:l.basis==='percent_fob'?`${l.amount}% FOB`:money(l.amount))+vat;const tiers=normalizeSimpleTiers(l.tiers||[]);return tiers.map((t,i)=>t.mode==='fixed'?`Hasta ${t.upTo} m³: ${money(t.amount)} fijo`:`De ${t.from} a ${t.upTo??'∞'} m³: +${money(t.rate)}/m³`).join(' · ')+vat}
function normalizeSimpleTiers(tiers=[]){if(tiers.some(t=>t.mode))return tiers.map((t,i,a)=>({...t,from:t.from??(i?Number(a[i-1].upTo||0):0)}));if(!tiers.length)return [{upTo:1,from:0,mode:'fixed',amount:500},{upTo:5,from:1,mode:'per_cbm',rate:500},{upTo:68,from:5,mode:'per_cbm',rate:400}];const first=tiers[0];if(tiers.length===2&&Number(first.upTo)===5&&Number(first.base)===500&&Number(first.included)===1){return [{upTo:1,from:0,mode:'fixed',amount:500},{upTo:5,from:1,mode:'per_cbm',rate:Number(first.rate||500)},{upTo:68,from:5,mode:'per_cbm',rate:Number(tiers[1]?.rate||400)}]};return tiers.map((t,i,a)=>({upTo:t.upTo??null,from:i?Number(a[i-1].upTo||0):0,mode:i===0?'fixed':'per_cbm',amount:Number(t.base||0),rate:Number(t.rate||0)}))}
function logProfilesTable(){return `<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Tipo</th><th>Ruta</th><th>Unidad</th><th>Componentes</th><th></th></tr></thead><tbody>${state.data.logisticsProfiles.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.type)}</td><td>${esc(p.route||'')}</td><td>${esc(p.unit||'')}</td><td>${(p.lines||[]).map(l=>`<small>${esc(l.name)}: ${esc(formulaLabel(l))}</small>`).join('<br>')}</td><td><button class="ghost" onclick="logModal('${p.id}')">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
function taxModal(pid){const p=state.data.taxProfiles.find(x=>x.id===pid)||{name:'General',duty:18,vat:21,vatAdditional:20,earnings:6,iibb:3,statisticalFee:3};openModal(pid?'Editar perfil impositivo':'Nuevo perfil impositivo',`<div class="form-grid"><div class="field span2"><label>Nombre</label><input id="tName" value="${esc(p.name)}"></div>${[['Derecho','duty'],['IVA','vat'],['IVA adicional','vatAdditional'],['Ganancia','earnings'],['IIBB','iibb'],['Tasa estadística','statisticalFee']].map(([l,k])=>`<div class="field"><label>${l} %</label><input type="number" step=".01" id="t_${k}" value="${p[k]||0}"></div>`).join('')}</div><div class="notice"><b>Uso del producto</b><br>COMERCIAL aplica todos los impuestos del perfil. BIEN DE USO aplica solo Derecho + IVA. PARTICULAR aplica Derecho + IVA + Ganancia 11%.</div><br><button class="btn primary" onclick="saveTax('${pid||''}')">Guardar perfil</button>`)}
async function saveTax(pid){const body={id:pid||undefined,name:$('#tName').value,duty:+$('#t_duty').value,vat:+$('#t_vat').value,vatAdditional:+$('#t_vatAdditional').value,earnings:+$('#t_earnings').value,iibb:+$('#t_iibb').value,statisticalFee:+$('#t_statisticalFee').value,active:true};await api(pid?`/api/taxProfiles/${pid}`:'/api/taxProfiles',{method:pid?'PUT':'POST',body});closeModal();await refresh();route('profiles')}
function logModal(pid){const p=state.data.logisticsProfiles.find(x=>x.id===pid)||{name:'Nuevo perfil',type:'LCL',route:'China → Argentina',unit:'CBM',containerType:'40HQ',capacityCbm:68,lines:[{code:'freight',name:'Flete internacional',basis:'cbm',amount:90},{code:'destination',name:'Flete / Depósito / Canal rojo / Verificación',basis:'tiered_cbm',tiers:[{from:0,upTo:1,mode:'fixed',amount:500},{from:1,upTo:5,mode:'per_cbm',rate:500},{from:5,upTo:68,mode:'per_cbm',rate:400}]}]};openModal(pid?'Editar perfil logístico':'Nuevo perfil logístico',`<div class="form-grid"><div class="field span2"><label>Nombre</label><input id="lName" value="${esc(p.name)}"></div><div class="field"><label>Tipo</label><input id="lType" value="${esc(p.type)}"></div><div class="field"><label>Unidad</label><select id="lUnit"><option ${p.unit==='CBM'?'selected':''}>CBM</option><option ${p.unit==='KG'?'selected':''}>KG</option><option ${p.unit==='container'?'selected':''}>container</option></select></div><div class="field span2"><label>Tipo de contenedor</label><select id="lContainerType"><option ${p.containerType==='20GP'?'selected':''}>20GP</option><option ${p.containerType==='40GP'?'selected':''}>40GP</option><option ${(!p.containerType||p.containerType==='40HQ')?'selected':''}>40HQ</option></select></div><div class="field span2"><label>Capacidad comercial máxima (CBM)</label><input type="number" step=".1" id="lCapacity" value="${p.capacityCbm||68}"></div><div class="field span4"><label>Ruta</label><input id="lRoute" value="${esc(p.route||'')}"></div></div><div class="notice"><b>Capacidad:</b> para FCL usamos el límite comercial del contenedor. 40HQ queda por defecto en <b>68 m³</b>, pero es editable.</div><br><h4>Componentes del costo</h4><p class="muted">Cada concepto puede ser fijo, por CBM, por KG, % FOB o fórmula por tramos. También definís si es neto, + IVA 21% o IVA incluido.</p><div id="lines">${(p.lines||[]).map((l,i)=>lineHtml(l,i)).join('')}</div><button class="ghost" onclick="addLine()">+ Agregar concepto</button><br><br><button class="btn primary" onclick="saveLog('${pid||''}')">Guardar perfil</button>`)}
function lineHtml(l={},i=Date.now()){const tiers=normalizeSimpleTiers(l.tiers||[]);const vt=l.vatTreatment||'none';return `<div class="formula-line" data-line data-code="${esc(l.code||`line_${i}`)}"><div class="line-row"><input class="line-name" placeholder="Concepto" value="${esc(l.name||'')}"><select class="line-basis" onchange="toggleTierConfig(this)"><option value="fixed" ${l.basis==='fixed'?'selected':''}>Fijo</option><option value="cbm" ${l.basis==='cbm'?'selected':''}>Por CBM</option><option value="kg" ${l.basis==='kg'?'selected':''}>Por KG</option><option value="percent_fob" ${l.basis==='percent_fob'?'selected':''}>% FOB</option><option value="tiered_cbm" ${l.basis==='tiered_cbm'?'selected':''}>Tramos simples por CBM</option></select><input class="line-amount" type="number" step=".01" value="${l.amount||0}" ${l.basis==='tiered_cbm'?'disabled':''}><select class="line-vat"><option value="none" ${vt==='none'?'selected':''}>Neto / sin IVA</option><option value="plus_vat" ${vt==='plus_vat'?'selected':''}>+ IVA 21%</option><option value="included_vat" ${vt==='included_vat'?'selected':''}>IVA incluido</option></select><button class="ghost" onclick="this.closest('[data-line]').remove()">✕</button></div><div class="tier-config ${l.basis==='tiered_cbm'?'':'hidden'}"><div class="tier-title"><div><b>Tramos simples por volumen</b><small>Primero definís el fijo inicial y después cuánto agregar por cada m³ adicional.</small></div></div><div class="tiers">${tiers.map(t=>tierHtml(t)).join('')}</div><button class="ghost" onclick="addTier(this)">+ Agregar tramo</button><div class="tier-preview"><b>Vista previa</b><label>CBM de prueba <input type="number" class="tier-test-cbm" step=".1" value="8" oninput="updateTierPreview(this)"></label><strong class="tier-test-result">—</strong></div></div></div>`}
function tierHtml(t={}){const mode=t.mode||'per_cbm';return `<div class="tier-row simple-tier" data-tier><label>Desde m³<input class="tier-from" type="number" step=".001" value="${t.from??0}" readonly></label><label>Hasta m³<input class="tier-up" type="number" step=".001" placeholder="∞" value="${t.upTo??''}" oninput="syncTierRanges(this);updateTierPreview(this)"></label><label>Tipo<select class="tier-mode" onchange="toggleTierMode(this);updateTierPreview(this)"><option value="fixed" ${mode==='fixed'?'selected':''}>Monto fijo</option><option value="per_cbm" ${mode==='per_cbm'?'selected':''}>Agregar por m³</option></select></label><label class="tier-fixed-label ${mode==='fixed'?'':'hidden'}">Monto fijo USD<input class="tier-amount" type="number" step=".01" value="${t.amount||0}" oninput="updateTierPreview(this)"></label><label class="tier-rate-label ${mode==='per_cbm'?'':'hidden'}">USD por m³ adicional<input class="tier-rate" type="number" step=".01" value="${t.rate||0}" oninput="updateTierPreview(this)"></label><button class="ghost" onclick="removeTier(this)">✕</button></div>`}
function toggleTierConfig(sel){const box=sel.closest('[data-line]');const is=sel.value==='tiered_cbm';box.querySelector('.tier-config').classList.toggle('hidden',!is);box.querySelector('.line-amount').disabled=is;}
function addTier(btn){const list=btn.previousElementSibling;const rows=[...list.querySelectorAll('[data-tier]')];const from=rows.length?Number(rows[rows.length-1].querySelector('.tier-up').value||0):0;list.insertAdjacentHTML('beforeend',tierHtml({from,upTo:null,mode:'per_cbm',rate:0}));updateTierPreview(btn)}
function toggleTierMode(sel){const row=sel.closest('[data-tier]');row.querySelector('.tier-fixed-label').classList.toggle('hidden',sel.value!=='fixed');row.querySelector('.tier-rate-label').classList.toggle('hidden',sel.value!=='per_cbm')}
function syncTierRanges(el){const list=el.closest('.tiers');const rows=[...list.querySelectorAll('[data-tier]')];rows.forEach((r,i)=>{r.querySelector('.tier-from').value=i?Number(rows[i-1].querySelector('.tier-up').value||0):0})}
function removeTier(btn){const list=btn.closest('.tiers');btn.closest('[data-tier]').remove();if(list){const first=list.querySelector('.tier-up');if(first)syncTierRanges(first)}updateTierPreview(list)}
function calcSimpleTiers(tiers,cbm){const volume=Math.max(0,Number(cbm||0));if(volume<=0)return 0;let total=0;for(const t of tiers){const from=Number(t.from||0),up=t.upTo==null?Infinity:Number(t.upTo);if(volume<=from)continue;if(t.mode==='fixed'){total+=Number(t.amount||0)}else{total+=Math.max(0,Math.min(volume,up)-from)*Number(t.rate||0)}if(volume<=up)break}return total}
function updateTierPreview(el){const cfg=el.closest?.('.tier-config')||el.querySelector?.('.tier-config')||el.closest?.('[data-line]')?.querySelector('.tier-config');if(!cfg)return;const tiers=[...cfg.querySelectorAll('[data-tier]')].map(r=>({from:+r.querySelector('.tier-from').value||0,upTo:r.querySelector('.tier-up').value===''?null:+r.querySelector('.tier-up').value,mode:r.querySelector('.tier-mode').value,amount:+r.querySelector('.tier-amount')?.value||0,rate:+r.querySelector('.tier-rate')?.value||0}));const cbm=+cfg.querySelector('.tier-test-cbm').value||0;cfg.querySelector('.tier-test-result').textContent=`${cbm.toFixed(2)} m³ → ${money(calcSimpleTiers(tiers,cbm))}`}
function addLine(){$('#lines').insertAdjacentHTML('beforeend',lineHtml({name:'Nuevo concepto',basis:'fixed',amount:0}))}
async function saveLog(pid){const lines=[...document.querySelectorAll('[data-line]')].map((r,i)=>{const basis=r.querySelector('.line-basis').value;const out={code:r.dataset.code||`line_${i}`,name:r.querySelector('.line-name').value,basis,amount:+r.querySelector('.line-amount').value||0,vatTreatment:r.querySelector('.line-vat')?.value||'none',vatRate:21};if(basis==='tiered_cbm')out.tiers=[...r.querySelectorAll('[data-tier]')].map(t=>({from:+t.querySelector('.tier-from').value||0,upTo:t.querySelector('.tier-up').value===''?null:+t.querySelector('.tier-up').value,mode:t.querySelector('.tier-mode').value,amount:+t.querySelector('.tier-amount')?.value||0,rate:+t.querySelector('.tier-rate')?.value||0}));return out});const body={id:pid||undefined,name:$('#lName').value,type:$('#lType').value,unit:$('#lUnit').value,containerType:$('#lContainerType')?.value||'',capacityCbm:+($('#lCapacity')?.value||0),route:$('#lRoute').value,lines,active:true};await api(pid?`/api/logisticsProfiles/${pid}`:'/api/logisticsProfiles',{method:pid?'PUT':'POST',body});closeModal();await refresh();route('profiles')}
function quotes(){shell('Cotizaciones','Historial de cotizaciones guardadas.',`<button class="btn primary" onclick="newQuote('product')">+ Nueva cotización de productos</button>`);$('#pageBody').innerHTML=`<div class="card">${quotesTable(state.data.quotes)}</div>`}
function logistics(){shell('Cotizaciones logísticas','Cotizá LCL, FCL, aéreo, courier y fiscal con perfiles y fórmulas editables.',`<button class="btn primary" onclick="newQuote('logistics')">+ Nueva cotización logística</button>`);$('#pageBody').innerHTML=`<div class="card">${quotesTable(state.data.quotes)}</div>`}
function newQuote(mode='logistics'){state.draft={mode,taxProfileId:state.data.taxProfiles.find(x=>x.isDefault)?.id||state.data.taxProfiles[0]?.id,logisticsProfileId:state.data.logisticsProfiles[0]?.id,fob:0,cbm:0,kg:0,insurancePct:2,clientName:'',reference:'',description:'',status:'draft',items:[],taxMode:mode==='logistics'?'product':'shipment',shipmentUse:'commercial',honorariaApplies:false,honorariaBasePct:50,honorariaRatePct:30};renderQuoteBuilder()}
function merchandisePicker(){return `<div class="card"><div class="section-head"><div><h3>1. Ítems de mercadería</h3><small>Cada ítem puede tener impuestos distintos.</small></div><button class="btn primary" onclick="addMerchandiseItem()">+ Agregar ítem</button></div><div id="selectedMerchandise"></div></div><br>`}
function addMerchandiseItem(){const id=`mi_${Date.now()}_${Math.random().toString(36).slice(2,6)}`;state.draft.items.push({productId:id,sku:'',name:'Nuevo ítem',unitFob:0,unitCbm:0,unitKg:0,qty:1,agentCommissionPct:0,taxProfileId:state.draft.taxProfileId||'general',productUse:'commercial'});state.draft.taxMode='product';syncMerchandiseToDraft();renderMerchandiseItems();syncQuoteInputs();readQuote()}
function changeMerchItem(id,field,val){const i=state.draft.items.find(x=>x.productId===id);if(!i)return;if(['qty','unitFob','unitCbm','unitKg'].includes(field))i[field]=Math.max(field==='qty'?1:0,+val||0);else i[field]=val;i.agentCommissionPct=0;state.draft.taxMode='product';syncMerchandiseToDraft();renderMerchandiseItems();syncQuoteInputs();readQuote()}
function removeMerchandiseItem(id){state.draft.items=state.draft.items.filter(x=>x.productId!==id);syncMerchandiseToDraft();renderMerchandiseItems();syncQuoteInputs();readQuote()}
function syncMerchandiseToDraft(){state.draft.items=(state.draft.items||[]).map(i=>({...i,agentCommissionPct:0}));state.draft.fob=state.draft.items.reduce((s,i)=>s+(+i.unitFob||0)*(+i.qty||1),0);state.draft.cbm=state.draft.items.reduce((s,i)=>s+(+i.unitCbm||0)*(+i.qty||1),0);state.draft.kg=state.draft.items.reduce((s,i)=>s+(+i.unitKg||0)*(+i.qty||1),0);state.draft.agentCommissionTotal=0;state.draft.taxMode='product'}
function renderMerchandiseItems(){const el=$('#selectedMerchandise');if(!el)return;const items=state.draft.items||[];el.innerHTML=items.length?`<div class="table-wrap"><table><thead><tr><th>Ítem / descripción</th><th>Cant.</th><th>FOB unit.</th><th>CBM unit.</th><th>KG unit.</th><th>Uso</th><th>Perfil impositivo</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><input style="min-width:150px" value="${esc(i.name||'')}" onchange="changeMerchItem('${i.productId}','name',this.value)"></td><td><input class="qty-input" type="number" min="1" value="${i.qty||1}" onchange="changeMerchItem('${i.productId}','qty',this.value)"></td><td><input class="qty-input" type="number" step=".01" min="0" value="${i.unitFob||0}" onchange="changeMerchItem('${i.productId}','unitFob',this.value)"></td><td><input class="qty-input" type="number" step=".001" min="0" value="${i.unitCbm||0}" onchange="changeMerchItem('${i.productId}','unitCbm',this.value)"></td><td><input class="qty-input" type="number" step=".01" min="0" value="${i.unitKg||0}" onchange="changeMerchItem('${i.productId}','unitKg',this.value)"></td><td><select onchange="changeMerchItem('${i.productId}','productUse',this.value)"><option value="commercial" ${i.productUse==='commercial'?'selected':''}>COMERCIAL</option><option value="capital_good" ${(i.productUse==='capital_good'||i.productUse==='bien_de_uso')?'selected':''}>BIEN DE USO</option><option value="particular" ${i.productUse==='particular'?'selected':''}>PARTICULAR</option></select></td><td><select onchange="changeMerchItem('${i.productId}','taxProfileId',this.value)">${state.data.taxProfiles.map(t=>`<option value="${t.id}" ${i.taxProfileId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></td><td><button class="ghost danger" onclick="removeMerchandiseItem('${i.productId}')">Quitar</button></td></tr>`).join('')}</tbody></table></div><div class="notice" style="margin-top:10px"><b>Totales mercadería:</b> FOB ${money(state.draft.fob)} · ${Number(state.draft.cbm||0).toFixed(3)} CBM · ${Number(state.draft.kg||0).toFixed(2)} KG</div>`:'<div class="notice">Agregá al menos un ítem de mercadería. Cada uno puede usar un perfil impositivo distinto.</div>'}
function productPicker(){const ps=state.data.products||[];return `<div class="card"><h3>1. Agregar productos</h3><div class="toolbar"><input id="quoteProductSearch" placeholder="Buscar SKU o producto..." oninput="renderQuoteProductList()"><small>${ps.length} productos disponibles</small></div><div id="quoteProductList"></div></div><br><div class="card"><h3>2. Productos seleccionados</h3><div id="selectedProducts"></div></div><br>`}
function renderQuoteProductList(){const q=($('#quoteProductSearch')?.value||'').toLowerCase();const ps=(state.data.products||[]).filter(p=>`${p.sku} ${p.name} ${p.category}`.toLowerCase().includes(q)).slice(0,50);const el=$('#quoteProductList');if(!el)return;el.innerHTML=`<div class="table-wrap quote-products"><table><thead><tr><th></th><th>SKU</th><th>Producto</th><th>Lista / proveedor / FOB</th><th>CBM</th><th>Comisión compra</th><th></th></tr></thead><tbody>${ps.map(p=>{const prices=(p.prices||[]).length?p.prices:[{id:'base',listName:'Precio base',currency:'USD',price:p.fob||0,moq:p.moq||0,isDefault:true}];return `<tr><td><img class="thumb" src="${esc(p.imageUrl||'/assets/shenzhen-logo.png')}"></td><td>${esc(p.sku||p.id)}</td><td>${esc(p.name)}</td><td><select id="priceSel_${p.id}" style="min-width:230px">${prices.map(pr=>{const sup=(state.data.suppliers||[]).find(s=>s.id===pr.supplierId);return `<option value="${esc(pr.id)}" ${pr.isDefault?'selected':''}>${esc(pr.listName||'Standard')} · ${esc(sup?.publicAlias||'Sin proveedor')} · ${esc(pr.currency||'USD')} ${Number(pr.price||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:4})}${pr.moq?` · MOQ ${pr.moq}`:''}</option>`}).join('')}</select></td><td>${Number(p.cbm||0).toFixed(3)}</td><td>${pct(p.agentCommissionPct||0)}</td><td><button class="btn primary" onclick="addProductToQuote('${p.id}')">+ Agregar</button></td></tr>`}).join('')||'<tr><td colspan="7">No hay productos.</td></tr>'}</tbody></table></div>`}
function addProductToQuote(pid){const p=state.data.products.find(x=>x.id===pid);if(!p)return;const prices=(p.prices||[]).length?p.prices:[{id:'base',listName:'Precio base',currency:'USD',price:p.fob||0,moq:p.moq||0,isDefault:true}];const selectedId=$(`#priceSel_${pid}`)?.value;const pr=prices.find(x=>String(x.id)===String(selectedId))||prices.find(x=>x.isDefault)||prices[0];const lineKey=`${pid}__${pr.id||'base'}`;const existing=state.draft.items.find(x=>x.productId===lineKey);if(existing)existing.qty+=1;else{const sup=(state.data.suppliers||[]).find(s=>s.id===pr.supplierId);state.draft.items.push({productId:lineKey,sourceProductId:p.id,priceId:pr.id||'base',priceListName:pr.listName||'Precio base',supplierId:pr.supplierId||'',supplierAlias:sup?.publicAlias||'',currency:pr.currency||'USD',sku:p.sku||p.id,name:p.name,imageUrl:p.imageUrl||'',unitFob:+pr.price||+p.fob||0,unitCbm:+p.cbm||0,unitKg:+p.kg||0,qty:1,agentCommissionPct:+p.agentCommissionPct||0,taxProfileId:p.taxProfileId||'general',productUse:p.productUse||'commercial'});}if(state.draft.items.length===1&&p.taxProfileId)state.draft.taxProfileId=p.taxProfileId;syncProductsToDraft();renderSelectedProducts();syncQuoteInputs();readQuote();}
function changeItemQty(pid,val){const it=state.draft.items.find(x=>x.productId===pid);if(!it)return;it.qty=Math.max(1,+val||1);syncProductsToDraft();renderSelectedProducts();syncQuoteInputs();readQuote();}
function changeItemCommission(pid,val){const it=state.draft.items.find(x=>x.productId===pid);if(!it)return;it.agentCommissionPct=Math.max(0,+val||0);syncProductsToDraft();renderSelectedProducts();syncQuoteInputs();readQuote();}
function removeQuoteItem(pid){state.draft.items=state.draft.items.filter(x=>x.productId!==pid);syncProductsToDraft();renderSelectedProducts();syncQuoteInputs();readQuote();}
function syncProductsToDraft(){state.draft.fob=state.draft.items.reduce((s,i)=>s+i.unitFob*i.qty,0);state.draft.cbm=state.draft.items.reduce((s,i)=>s+i.unitCbm*i.qty,0);state.draft.kg=state.draft.items.reduce((s,i)=>s+i.unitKg*i.qty,0);state.draft.agentCommissionTotal=state.draft.items.reduce((s,i)=>s+(i.unitFob*i.qty*((+i.agentCommissionPct||0)/100)),0);state.draft.description=state.draft.items.map(i=>`${i.qty}x ${i.name}`).join(', ');}
function syncQuoteInputs(){if($('#qFob'))$('#qFob').value=state.draft.fob.toFixed(2);if($('#qCbm'))$('#qCbm').value=state.draft.cbm.toFixed(3);if($('#qKg'))$('#qKg').value=state.draft.kg.toFixed(2);if($('#qDesc'))$('#qDesc').value=state.draft.description;if($('#qTax'))$('#qTax').value=state.draft.taxProfileId;if($('#qLog'))$('#qLog').value=state.draft.logisticsProfileId;}
function useLabel(u){return u==='particular'?'PARTICULAR':(u==='capital_good'||u==='bien_de_uso')?'BIEN DE USO':'COMERCIAL'}
function changeItemUse(pid,val){const it=state.draft.items.find(x=>x.productId===pid);if(!it)return;it.productUse=val;state.draft.taxMode='product';const mode=$('#qTaxMode');if(mode)mode.value='product';readQuote()}
function changeItemTax(pid,val){const it=state.draft.items.find(x=>x.productId===pid);if(!it)return;it.taxProfileId=val;state.draft.taxMode='product';const mode=$('#qTaxMode');if(mode)mode.value='product';readQuote()}
function renderSelectedProducts(){const el=$('#selectedProducts');if(!el)return;const items=state.draft.items||[];el.innerHTML=items.length?`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Cant.</th><th>FOB total</th><th>CBM total</th><th>Comisión compra</th><th>Uso</th><th>Perfil impositivo</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><b>${esc(i.name)}</b><br><small>${esc(i.sku)}${i.priceListName?` · ${esc(i.priceListName)}`:''}${i.supplierAlias?` · ${esc(i.supplierAlias)}`:''}<br>${money(i.unitFob)} unit.</small></td><td><input class="qty-input" type="number" min="1" value="${i.qty}" onchange="changeItemQty('${i.productId}',this.value)"></td><td>${money(i.unitFob*i.qty)}</td><td>${(i.unitCbm*i.qty).toFixed(3)}</td><td><input class="qty-input" type="number" step=".01" min="0" value="${i.agentCommissionPct||0}" onchange="changeItemCommission('${i.productId}',this.value)"><small>${money((i.unitFob*i.qty)*(+i.agentCommissionPct||0)/100)}</small></td><td><select onchange="changeItemUse('${i.productId}',this.value)"><option value="commercial" ${i.productUse==='commercial'?'selected':''}>COMERCIAL</option><option value="capital_good" ${(i.productUse==='capital_good'||i.productUse==='bien_de_uso')?'selected':''}>BIEN DE USO</option><option value="particular" ${i.productUse==='particular'?'selected':''}>PARTICULAR</option></select></td><td><select onchange="changeItemTax('${i.productId}',this.value)">${state.data.taxProfiles.map(t=>`<option value="${t.id}" ${i.taxProfileId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></td><td><button class="ghost" onclick="removeQuoteItem('${i.productId}')">Quitar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">Todavía no agregaste productos. Buscá uno arriba y tocá <b>+ Agregar</b>.</div>'}
function renderQuoteBuilder(){const d=state.draft;const isLog=d.mode==='logistics';shell(isLog?'Nueva cotización logística':'Nueva cotización de productos',isLog?'Servicios logísticos + aduana sobre mercadería del cliente.':'Valores editables en tiempo real.',`<button class="btn" onclick="saveQuote(false)">Guardar borrador</button> <button class="btn primary" onclick="saveQuote(true)">Guardar y emitir</button>`);$('#pageBody').innerHTML=`${isLog?merchandisePicker():productPicker()}<div class="grid split"><div><div class="card"><h3>${isLog?'2. Datos de cotización':'3. Datos de cotización'}</h3><div class="form-grid"><div class="field span2"><label>Cliente</label><input id="qClient" value="${esc(d.clientName)}" oninput="readQuote()"></div><div class="field span2"><label>${isLog?'Ítem / Referencia':'Producto / Referencia'}</label><input id="qReference" value="${esc(d.reference||'')}" placeholder="Ej. Línea de producción + repuestos" oninput="readQuote()"></div><div class="field span4"><label>Descripción / notas</label><input id="qDesc" value="${esc(d.description||'')}" oninput="readQuote()"></div><div class="field"><label>FOB USD</label><input id="qFob" type="number" value="${d.fob}" readonly></div><div class="field"><label>CBM total</label><input id="qCbm" type="number" value="${d.cbm}" readonly></div><div class="field"><label>KG total</label><input id="qKg" type="number" value="${d.kg}" readonly></div><div class="field"><label>Seguro %</label><input id="qIns" type="number" step=".01" value="${d.insurancePct}" oninput="readQuote()"></div>${isLog?`<div class="field span2"><label>Impuestos</label><input value="Por ítem de mercadería" readonly></div>`:`<div class="field"><label>Impuestos</label><select id="qTaxMode" onchange="readQuote();renderSelectedProducts()"><option value="shipment" ${d.taxMode!=='product'?'selected':''}>Por envío</option><option value="product" ${d.taxMode==='product'?'selected':''}>Por producto</option></select></div><div class="field"><label>Uso del envío</label><select id="qShipmentUse" onchange="readQuote()"><option value="commercial">COMERCIAL</option><option value="capital_good">BIEN DE USO</option><option value="particular">PARTICULAR</option></select></div><div class="field span2"><label>Perfil impositivo del envío</label><select id="qTax" onchange="readQuote()">${state.data.taxProfiles.map(x=>`<option value="${x.id}" ${d.taxProfileId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}<div class="field span2"><label>Perfil logístico</label><select id="qLog" onchange="readQuote()">${state.data.logisticsProfiles.map(x=>`<option value="${x.id}" ${d.logisticsProfileId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div></div><br><div class="card"><h3>Honorarios del envío</h3><div class="form-grid"><div class="field"><label>Aplica</label><select id="qHonApplies" onchange="readQuote()"><option value="0" ${!d.honorariaApplies?'selected':''}>No</option><option value="1" ${d.honorariaApplies?'selected':''}>Sí</option></select></div><div class="field"><label>Base para simular impuestos</label><select id="qHonBase" onchange="readQuote()"><option value="50" ${d.honorariaBasePct==50?'selected':''}>50%</option><option value="70" ${d.honorariaBasePct==70?'selected':''}>70%</option></select></div><div class="field"><label>% sobre ahorro</label><input id="qHonRate" type="number" step=".01" value="${d.honorariaRatePct||30}" oninput="readQuote()"></div></div></div><br><div class="card"><h3>${isLog?'Impuestos por ítem':'Perfil impositivo'}</h3><div id="taxPreview"></div></div><br><div class="card"><h3>Gastos logísticos</h3><div id="logPreview"></div><div id="logisticsMetrics"></div></div></div><div><div class="card sticky-summary"><h3>Resumen de la cotización</h3><div id="quoteSummary"></div></div></div></div>`;if(isLog)renderMerchandiseItems();else{renderQuoteProductList();renderSelectedProducts()}readQuote()}
function readQuote(){state.draft.clientName=$('#qClient')?.value||'';state.draft.reference=$('#qReference')?.value||state.draft.reference||'';state.draft.description=$('#qDesc')?.value||'';if(state.draft.mode==='logistics'){syncMerchandiseToDraft();state.draft.taxMode='product'}else{state.draft.taxMode=$('#qTaxMode')?.value||'shipment';state.draft.shipmentUse=$('#qShipmentUse')?.value||'commercial';state.draft.taxProfileId=$('#qTax')?.value||state.draft.taxProfileId}state.draft.insurancePct=+($('#qIns')?.value||0);state.draft.logisticsProfileId=$('#qLog')?.value||state.draft.logisticsProfileId;state.draft.honorariaApplies=$('#qHonApplies')?.value==='1';state.draft.honorariaBasePct=+($('#qHonBase')?.value||50);state.draft.honorariaRatePct=+($('#qHonRate')?.value||30);syncQuoteInputs();const t=state.data.taxProfiles.find(x=>x.id===state.draft.taxProfileId)||{};const l=state.data.logisticsProfiles.find(x=>x.id===state.draft.logisticsProfileId)||{};if($('#taxPreview')){if(state.draft.mode==='logistics')$('#taxPreview').innerHTML=(state.draft.items||[]).map(i=>{const tp=state.data.taxProfiles.find(x=>x.id===i.taxProfileId)||{};return `<div class="summary-row"><span><b>${esc(i.name)}</b><br><small>${useLabel(i.productUse)} · ${esc(tp.name||i.taxProfileId||'General')}</small></span><span>Der. ${pct(tp.duty)} · IVA ${pct(tp.vat)}</span></div>`}).join('')||'<div class="notice">Agregá ítems para ver sus impuestos.</div>';else $('#taxPreview').innerHTML=`<div><b>Modo:</b> ${state.draft.taxMode==='product'?'POR PRODUCTO':'POR ENVÍO'} · <b>Uso:</b> ${useLabel(state.draft.shipmentUse)}</div>`}if($('#logPreview'))$('#logPreview').innerHTML=(l.lines||[]).map(x=>`<div class="summary-row"><span>${esc(x.name)}<br><small>${esc(formulaLabel(x))}</small></span><b class="computed-line">—</b></div>`).join('');calculateCurrent(t,l)}
async function calculateCurrent(t,l){state.calc=await api('/api/calculate',{method:'POST',body:{...state.draft,taxProfile:t,logisticsProfile:l}});const c=state.calc;(c.logisticsLines||[]).forEach((line,i)=>{const els=document.querySelectorAll('.computed-line');if(els[i])els[i].textContent=money(line.total)});const lm=$('#logisticsMetrics');if(lm){const isContainer=Number(c.containerCapacityCbm||0)>0;lm.innerHTML=`<div class="logistics-kpis"><div><small>Logística all-in</small><strong>${money(c.logisticsTotal)}</strong></div><div><small>Costo efectivo por CBM</small><strong>${c.cbm>0?money(c.logisticsAllInPerCbm)+'/CBM':'—'}</strong></div></div>${isContainer?`<div class="container-meter"><div class="container-meter-head"><b>${esc(c.containerType||'Contenedor')}</b><span>${Number(c.cbm||0).toFixed(2)} / ${Number(c.totalContainerCapacity||c.containerCapacityCbm).toFixed(2)} m³ · ${Number(c.containerUtilizationPct||0).toFixed(1)}%</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100,Number(c.containerUtilizationPct||0))}%"></div></div></div>`:''}`;}if(!$('#quoteSummary'))return;const itemBlock=c.taxMode==='product'&&c.itemTaxes?.length?`<div class="notice"><b>${state.draft.mode==='logistics'?'Impuestos por ítem de mercadería':'Impuestos por producto'}</b>${c.itemTaxes.map(i=>`<div style="margin-top:6px">${esc(i.name)} · ${useLabel(i.productUse)} · <b>${money(i.taxesTotal)}</b></div>`).join('')}</div><br>`:'';const commissionRow=state.draft.mode==='product'?`<div class="summary-row"><span>Comisión agente compra</span><b>${money(c.agentCommissionTotal)}</b></div>`:'';const honorariaBlock=c.honorariaApplies?`<div class="notice" style="margin-bottom:12px"><b>Honorarios del envío</b><div style="margin-top:6px">FOB normal 100%: <b>${money(c.fob)}</b> → Impuestos <b>${money(c.normalTaxesTotal)}</b></div><div>FOB declarado ${c.honorariaBasePct}%: <b>${money(c.declaredFob)}</b> → Impuestos <b>${money(c.taxesTotal)}</b></div><div style="margin-top:4px">Ahorro impositivo: <b>${money(c.taxSavings)}</b> · Honorarios: <b>${money(c.honoraria)}</b></div><div style="margin-top:6px;color:#187a2f"><b>Recupero real: ${money(c.realRecovery)}</b></div></div>`:'';$('#quoteSummary').innerHTML=`${honorariaBlock}${itemBlock}<div class="summary-list"><div class="summary-row"><span>FOB mercadería</span><b>${money(c.fob)}</b></div><div class="summary-row"><span>CBM</span><b>${Number(c.cbm||0).toFixed(3)}</b></div>${commissionRow}<div class="summary-row"><span>Base CIF</span><b>${money(c.cif)}</b></div><div class="summary-row"><span><b>Total impuestos</b></span><b>${money(c.taxesTotal)}</b></div><div class="summary-row"><span>Logística neta</span><b>${money(c.logisticsNet)}</b></div><div class="summary-row"><span>IVA servicios logísticos</span><b>${money(c.logisticsVat)}</b></div><div class="summary-row"><span>Costos logísticos total</span><b>${money(c.logisticsTotal)}</b></div><div class="summary-row"><span>Recupero impuestos aduaneros</span><b>-${money(c.customsRecoverable)}</b></div><div class="summary-row"><span>Recupero IVA servicios</span><b>-${money(c.servicesVatRecoverable)}</b></div><div class="summary-total"><span>Total a abonar</span><span>${money(c.totalToPay)}</span></div></div>`}
async function saveQuote(emit){readQuote();if(!(state.draft.items||[]).length)return alert(state.draft.mode==='logistics'?'Agregá al menos un ítem de mercadería':'Agregá al menos un producto a la cotización');const r=await api('/api/quotes',{method:'POST',body:{...state.draft,status:emit?'issued':'draft'}});alert(`Guardada ${r.quoteNo}`);await refresh();route(state.draft.mode==='logistics'?'logistics':'quotes')}
function catalog(){shell('Generador de catálogos','Seleccioná productos y generá una presentación comercial.');const ps=state.data.products;$('#pageBody').innerHTML=`<div class="card"><div class="product-list">${ps.map(p=>`<div class="product-card"><img src="${esc(p.imageUrl||'/assets/shenzhen-logo.png')}"><h4>${esc(p.name)}</h4><small>${esc(p.sku||p.id)} · ${money(p.fob)} · ${Number(p.cbm||0).toFixed(3)} CBM</small></div>`).join('')||'<p>Cargá productos para generar catálogo.</p>'}</div></div>`}
function clients(){shell('Clientes','Base de clientes para cotizaciones.',`<button class="btn primary" onclick="clientModal()">+ Nuevo cliente</button>`);$('#pageBody').innerHTML=`<div class="card"><table><thead><tr><th>Nombre</th><th>Email</th><th>CUIT</th></tr></thead><tbody>${state.data.clients.map(c=>`<tr><td>${esc(c.name||'-')}</td><td>${esc(c.email||'-')}</td><td>${esc(c.taxId||'-')}</td></tr>`).join('')||'<tr><td colspan="3">Sin clientes.</td></tr>'}</tbody></table></div>`}
function clientModal(){openModal('Nuevo cliente',`<div class="form-grid"><div class="field span2"><label>Nombre</label><input id="cName"></div><div class="field"><label>Email</label><input id="cEmail"></div><div class="field"><label>CUIT</label><input id="cTax"></div></div><br><button class="btn primary" onclick="saveClient()">Guardar</button>`)}
async function saveClient(){await api('/api/clients',{method:'POST',body:{name:$('#cName').value,email:$('#cEmail').value,taxId:$('#cTax').value}});closeModal();await refresh();route('clients')}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
async function refresh(){state.data=await api('/api/bootstrap');applyTenant();renderNav()}
async function setTenant(t){state.tenantId=t;localStorage.setItem('tenantId',t);await refresh();route('dashboard')}
function switchTenant(){$('#tenantSelect').focus()}
boot();
